def test_monitor_flag_rate_none_counts_as_not_flagged():
    # SPEC section 1: None (like False) is not flagged, but still counts in the denominator.
    events = [{"flagged": True}, {"flagged": None}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 0.25
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_dedupe_transcripts_keeps_last_duplicate():
    # SPEC section 5: the last record with a given id wins; result sorted by day, then id.
    from safety_evals.loader import dedupe_transcripts

    events = [
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 5, "flagged": False},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "a", "day": 1, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": None},
    ]
